public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the chat members permissions. Supported only for basic groups and supergroups. Requires can_restrict_members administrator right
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetChatPermissionsAsync(long chatId = default, ChatPermissions permissions = default)
    {

           using var activity =  StartCallActivity("SetChatPermissionsAsync", typeof(SetChatPermissions).FullName ?? "SetChatPermissionsAsync");

           try
           {
             return client.SetChatPermissionsAsync(chatId, permissions);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
